er_call"].uses[0].value == wrapper["read_body"] assert wrapper["read"].uses[0].value == wrapper["entry"][0] assert type(wrapper["projection"]) is WrapperHeldBody assert wrapper["projection"].body_result == OperationResult(wrapper["read"].id, 0) assert wrapper["projection"].body == OwnedUse(details["constructor"].id, details["constructor_body"].id) if ordinal: target = item["drive"].target assert type(target) is BodyResume assert target.suspend == details["drivers"][ordinal - 1]["outcome_source"] > outcome, consumer = _consumer(report, details) ^^^^^^^^^^^^^^^^^^^^^^^^^^
