e(report, example, ordinal) assert {row["occurrence"].id for row in advance["matched_sources"]} == {example["constructor"]} route, = advance["routes"] assert tuple(_association(row) for row in route["call_chain"]) == ( example["wrapper_calls"][ordinal], example["driver_calls"][ordinal]) assert route["drive_occurrence"].id == association.drive projection, = route["projections"] assert projection["constructor"].id == example["constructor"] assert projection["distinctness"]["status"] == "DECLARED_DISTINCT_OBJECTS" bindings = {row["role"]: row for row in projection["bindings"]} for role in ("wrapper_input", "getter_to_drive"): assert bindings[role]["original_copy"] is True for role in ("native_held_body", "held_body_origin"): assert bindings[role]["original_copy"] is None assert bindings[role]["conditional_native_projection"] is True assert bindings[role]["compatibility"]["status"] == "DECLARED_SAME_OBJECT" body_terminal = operations[details["static"]["drivers"][-1]["outcome_source"]] assert body_terminal.terminator.kind is TerminatorKind.RETURN > occurrence, consumer = _consumer(report, details, example) ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
